insert into public.quiz_settings (id,enabled,deadline_at) values (1,true,'2026-10-27T00:00:00+07:00') on conflict (id) do nothing;
insert into public.questions (position,text,options,correct) values (1,'5ส ย่อมาจากอะไร?','["สะสาง สะดวก สะอาด สร้างมาตรฐาน สร้างวินัย", "สะสม สะดวก สะอาด สร้างสรรค์ สื่อสาร", "สะสาง สะสม สะอาด สร้างสุข สรุป", "สะดวก สวยงาม สงบ สบาย สะสม"]'::jsonb,0) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (2,'ข้อใดเป็นตัวอย่างของสะสาง?','["วางของทุกชนิดไว้รวมกัน", "แยกสิ่งจำเป็นออกจากสิ่งไม่จำเป็น", "เก็บของไว้โดยไม่ตรวจสอบ", "ย้ายของไปซ่อน"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (3,'จุดประสงค์หลักของสะดวกคืออะไร?','["จัดของให้ดูเยอะ", "ค้นหาและหยิบใช้งานได้ง่าย", "เพิ่มพื้นที่วางของไม่จำเป็น", "ลดจำนวนป้ายทั้งหมด"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (4,'หากพบสิ่งผิดปกติขณะทำความสะอาดควรทำอย่างไร?','["ปล่อยไว้ก่อน", "ปิดบังไม่ให้ใครเห็น", "รายงานและดำเนินการแก้ไขตามขั้นตอน", "รอจนมีคนอื่นพบ"]'::jsonb,2) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (5,'การตีกรอบตำแหน่งวางอุปกรณ์ช่วยเรื่องใด?','["เพิ่มสีสันอย่างเดียว", "ระบุตำแหน่งจัดเก็บให้ชัดเจน", "ทำให้อุปกรณ์หนักขึ้น", "ไม่ต้องตรวจนับอีก"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (6,'เมื่อหยิบอุปกรณ์ไปใช้งานเสร็จควรทำอย่างไร?','["คืนไว้ตำแหน่งที่กำหนด", "วางไว้ใกล้ตัว", "ฝากไว้กับใครก็ได้", "นำกลับบ้าน"]'::jsonb,0) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (7,'มาตรฐานการค้นหาสิ่งของในแผนกควรหาเจอภายในกี่วินาที?','["10 วินาที", "30 วินาที", "90 วินาที", "120 วินาที"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (8,'สิ่งของรับเข้าใหม่ควรทำสิ่งใดก่อน?','["ทิ้งทันที", "นำไปวางที่ใดก็ได้", "ติดป้ายรับเข้าใหม่และประเมินความจำเป็น", "นำไปใช้โดยไม่บันทึก"]'::jsonb,2) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (9,'การทำความสะอาดตามมาตรฐานแผนกกำหนดเป็นประจำวันใด?','["วันจันทร์", "วันพุธ", "วันเสาร์", "วันอาทิตย์"]'::jsonb,2) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (10,'หากของไม่อยู่ในตำแหน่งที่กำหนด ควรทำอย่างไร?','["ปล่อยไว้", "ตรวจสอบและนำกลับเข้าที่", "เปลี่ยนป้ายโดยไม่แจ้ง", "ย้ายของอื่นมาทับ"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (11,'เหตุใดต้องมีป้ายชื่อและตำแหน่งจัดเก็บ?','["เพื่อให้หยิบและคืนของถูกที่", "เพื่อใช้กระดาษให้หมด", "เพื่อให้พื้นที่ดูแคบลง", "เพื่อไม่ต้องจัดของ"]'::jsonb,0) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (12,'ข้อใดสอดคล้องกับการสร้างมาตรฐาน?','["แต่ละคนจัดของตามใจ", "ทำงานตามวิธีที่ตกลงร่วมกัน", "เปลี่ยนตำแหน่งทุกวัน", "ไม่ต้องตรวจติดตาม"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (13,'การสร้างวินัยใน 5ส หมายถึงอะไร?','["ทำเฉพาะก่อนตรวจ", "ปฏิบัติตามมาตรฐานอย่างต่อเนื่อง", "รอให้หัวหน้าบอกทุกครั้ง", "ทำเฉพาะเมื่อมีรางวัล"]'::jsonb,1) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (14,'หากพบสิ่งของไม่จำเป็นควรทำอย่างไร?','["คัดแยกและดำเนินการตามขั้นตอนสะสาง", "นำไปซ่อน", "วางกีดขวางทางเดิน", "เก็บไว้ตลอดไป"]'::jsonb,0) on conflict (position) do nothing;
insert into public.questions (position,text,options,correct) values (15,'ผลดีของกิจกรรม 5ส คือข้อใด?','["ทำให้หาของยากขึ้น", "เพิ่มความเสี่ยงสะดุด", "พื้นที่เป็นระเบียบ ปลอดภัย และทำงานสะดวก", "ทำให้ไม่ต้องมีมาตรฐาน"]'::jsonb,2) on conflict (position) do nothing;
