-- Run once in Supabase SQL Editor. All tables are private: browser clients have no direct access.
create table if not exists public.quiz_settings (id integer primary key check (id=1), enabled boolean not null default true, deadline_at timestamptz not null);
create table if not exists public.questions (id integer generated by default as identity primary key, position integer not null unique, text text not null, options jsonb not null, correct integer not null check (correct between 0 and 3));
create table if not exists public.submissions (id bigint generated always as identity primary key, name text not null, employee text not null unique, score integer not null, answers jsonb not null, receipt text not null, submitted_at timestamptz not null default now());
alter table public.quiz_settings enable row level security;
alter table public.questions enable row level security;
alter table public.submissions enable row level security;
revoke all on public.quiz_settings,public.questions,public.submissions from anon,authenticated;

-- รายชื่อพนักงาน: ใช้ชื่อที่เลือกแทนการกรอก Email/รหัสพนักงาน
create table if not exists public.employees (id bigint generated always as identity primary key, name text not null unique, active boolean not null default true);
alter table public.employees enable row level security;
revoke all on public.employees from anon,authenticated;
on conflict(name) do nothing;
